use semio_framework_job_context::{Generation,OperationId,OriginalNativeLease,OriginalNativeRetirement,OriginalTurnFailure,RetainedCloneGrant,StepContext};
use semio_framework_job_testing_caller::OriginalJobFixtureCaller;
use std::sync::atomic::{AtomicUsize,Ordering};
#[global_allocator]
static NATIVE_PARENT_HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
static DROPS:AtomicUsize=AtomicUsize::new(0);
static GRAPH_STEPS:AtomicUsize=AtomicUsize::new(0);
struct GraphChild{empty:bool}
impl OriginalNativeRetirement for GraphChild{fn close_on_source(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{assert_eq!(GRAPH_STEPS.swap(2,Ordering::Relaxed),1);cx.consume_fuel(1);self.empty=true;Ok(true)}fn terminal_is_empty(&self)->bool{self.empty}}
impl Drop for GraphChild{fn drop(&mut self){assert!(std::thread::panicking()||self.empty)}}
struct GraphParent{child:Option<OriginalNativeLease<GraphChild>>,empty:bool}
impl OriginalNativeRetirement for GraphParent{fn close_on_source(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{cx.consume_retained(semio_framework_job_context::RetainedCloneProgress{copied_items:1,..Default::default()})?;cx.consume_fuel(1);assert_eq!(GRAPH_STEPS.swap(1,Ordering::Relaxed),0);drop(self.child.take());self.empty=true;Ok(true)}fn terminal_is_empty(&self)->bool{self.empty&&self.child.is_none()}}
impl Drop for GraphParent{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty())}}
struct Native{empty:bool}
impl OriginalNativeRetirement for Native{
 fn close_on_source(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if cx.retirement_should_yield(){return Ok(false)}cx.consume_fuel(1);self.empty=true;Ok(true)}
 fn terminal_is_empty(&self)->bool{self.empty}
}
impl Drop for Native{fn drop(&mut self){assert!(std::thread::panicking()||self.empty);DROPS.fetch_add(1,Ordering::Relaxed);}}
fn prebirth(caller:&mut OriginalJobFixtureCaller,grant:RetainedCloneGrant){for _ in 0..64{let admitted=caller.turn(grant,|cx|cx.admit_original_return_table()).unwrap();let born=caller.receipt().retained_capacity_bytes;caller.record_born_capacity(born);if admitted{return}}panic!("original Source escrow table did not admit")}
fn clock()->Option<u64>{Some(1)}
fn stock()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:4096,maximum_copy_bytes:1048576,maximum_capacity_bytes:1048576,maximum_release_bytes:1048576,maximum_depth:128}}
#[test]
fn native_parent_survives_foreign_context_cancellation_and_return(){
 let cases:serde_json::Value=serde_json::from_str(include_str!("cases.json")).unwrap();assert_eq!(cases["slots"],8);assert_eq!(cases["graph"]["closeCallbacks"],serde_json::json!([1,0]));
 let grant=stock();let mut caller=OriginalJobFixtureCaller::admit(OperationId(610),Generation(1),grant,clock,100000,100000);prebirth(&mut caller,grant);
 let mut foreign=OriginalJobFixtureCaller::admit(OperationId(611),Generation(1),grant,clock,100000,100000);
 let mut native=Some(Native{empty:false});let mut owner:Option<OriginalNativeLease<Native>>=None;let mut child=None;
 let(result,denied)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(grant,|cx|{cx.narrow_original_work_budget(semio_framework_job_context::StepBudget::new(5,cx.deadline_us(),cx.retained_grant()))?;cx.admit_original_native(&mut native,&mut owner)}));assert!(!result.unwrap());assert!(native.is_some()&&owner.is_none());assert_eq!((denied.requested_bytes,denied.released_bytes),(0,0));assert_eq!(caller.receipt(),Default::default());
 let (result,birth)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(grant,|cx|cx.admit_original_native(&mut native,&mut owner)));
 assert!(result.unwrap());assert!(native.is_none());assert_eq!(birth.requested_bytes,caller.receipt().retained_capacity_bytes);assert_eq!(birth.released_bytes,0);
 let recipient=owner.as_ref().unwrap().recipient_identity();let mut one_item=false;let quantum=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:0,..grant};assert!(caller.turn(quantum,|cx|owner.as_mut().unwrap().with_native_borrow(cx,|_,cx|{cx.consume_retained(semio_framework_job_context::RetainedCloneProgress{copied_items:1,..Default::default()})?;cx.consume_fuel(1);one_item=true;Ok(())})).unwrap());assert_eq!(one_item,cases["guard"]["oneItemCallback"].as_bool().unwrap());assert_eq!(caller.receipt().copied_items,1);let mut entered=false;assert!(caller.turn(grant,|cx|owner.as_mut().unwrap().with_native_borrow(cx,|mut guard,cx|{guard.validate_context(cx)?;foreign.turn(grant,|other|{assert_eq!(guard.validate_context(other).is_err(),cases["guard"]["crossContextRefused"].as_bool().unwrap());assert!(guard.recipient_identity().validate_context(other).is_err());Ok(())})?;assert_eq!(guard.recipient_identity(),recipient);assert!(!guard.value_mut().empty);entered=true;Ok(())})).unwrap());assert_eq!(entered,cases["guard"]["sameRecipient"].as_bool().unwrap());let mut foreign_entered=false;let refused=foreign.turn(grant,|cx|owner.as_mut().unwrap().with_native_borrow(cx,|_,_|{foreign_entered=true;Ok(())})).is_err();assert_eq!(refused,cases["guard"]["foreignRefused"].as_bool().unwrap());assert_eq!(foreign_entered,cases["guard"]["foreignCallbackEntered"].as_bool().unwrap());assert!(caller.turn(grant,|cx|cx.original_native_retired_witness(recipient)).unwrap().is_none());assert!(foreign.turn(grant,|cx|cx.original_native_retired_witness(recipient)).is_err());
 assert!(caller.turn(grant,|cx|owner.as_ref().unwrap().lend(cx,&mut child)).unwrap());
 assert!(foreign.turn(grant,|cx|child.as_mut().unwrap().with_native(cx,|_,_|Ok(()))).is_err());
 caller.cancel().cancel_now();
 while owner.is_some(){caller.turn(grant,|cx|OriginalNativeLease::return_slot_step(&mut owner,cx)).unwrap();}
 assert!(!caller.turn(grant,|cx|cx.close_original_native_step()).unwrap());assert_eq!(DROPS.load(Ordering::Relaxed),0);
 assert!(caller.turn(grant,|cx|child.as_mut().unwrap().with_native(cx,|native,_|{assert!(!native.empty);Ok(())})).unwrap());
 while child.is_some(){caller.turn(grant,|cx|OriginalNativeLease::return_slot_step(&mut child,cx)).unwrap();}
 let mut released=0;while !caller.turn(grant,|cx|cx.close_original_native_step()).unwrap(){released+=caller.receipt().released_bytes;}
 released+=caller.receipt().released_bytes;assert_eq!(released,birth.requested_bytes);assert_eq!(DROPS.load(Ordering::Relaxed),1);
 assert!(caller.turn(grant,|cx|{let witness=cx.original_native_retired_witness(recipient)?.unwrap();assert!(witness.proves(recipient,cx));Ok(())}).is_ok());
 drop(owner);drop(child);caller.retire(grant);foreign.retire(grant);
 let mut detached=OriginalJobFixtureCaller::admit(OperationId(612),Generation(1),grant,clock,100000,100000);prebirth(&mut detached,grant);let mut input=Some(Native{empty:false});let mut owner:Option<OriginalNativeLease<Native>>=None;let mut child=None;
 let (result,birth)=semio_framework_trace::observe_heap_allocations_on_this_thread(||detached.turn(grant,|cx|cx.admit_original_native(&mut input,&mut owner)));assert!(result.unwrap());assert!(detached.turn(grant,|cx|owner.as_ref().unwrap().lend(cx,&mut child)).unwrap());detached.cancel().cancel_now();
 let (_,capture)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{drop(child);drop(owner);});assert_eq!((capture.requested_bytes,capture.released_bytes),(0,0));
 let mut released=0;while !detached.turn(grant,|cx|cx.close_original_native_step()).unwrap(){released+=detached.receipt().released_bytes;}released+=detached.receipt().released_bytes;assert_eq!(released,birth.requested_bytes);detached.retire(grant);
 let mut graph=OriginalJobFixtureCaller::admit(OperationId(613),Generation(1),grant,clock,100000,100000);prebirth(&mut graph,grant);let mut input=Some(GraphChild{empty:false});let mut owner:Option<OriginalNativeLease<GraphChild>>=None;let mut child=None;assert!(graph.turn(grant,|cx|cx.admit_original_native(&mut input,&mut owner)).unwrap());assert!(graph.turn(grant,|cx|owner.as_ref().unwrap().lend(cx,&mut child)).unwrap());let mut parent=Some(GraphParent{child,empty:false});let mut parent_loan=None;assert!(graph.turn(grant,|cx|cx.admit_original_native(&mut parent,&mut parent_loan)).unwrap());drop(owner);drop(parent_loan);while !graph.turn(grant,|cx|cx.close_original_native_step()).unwrap(){}assert_eq!(GRAPH_STEPS.load(Ordering::Relaxed),2);graph.retire(grant);
 let mut pair=OriginalJobFixtureCaller::admit(OperationId(614),Generation(1),grant,clock,100000,100000);prebirth(&mut pair,grant);let mut foreign=OriginalJobFixtureCaller::admit(OperationId(615),Generation(1),grant,clock,100000,100000);let mut left=None;let mut right=None;let mut alias=None;let mut input=Some(Native{empty:false});assert!(pair.turn(grant,|cx|cx.admit_original_native(&mut input,&mut left)).unwrap());let mut input=Some(Native{empty:false});assert!(pair.turn(grant,|cx|cx.admit_original_native(&mut input,&mut right)).unwrap());assert!(pair.turn(grant,|cx|left.as_ref().unwrap().lend(cx,&mut alias)).unwrap());
 assert!(pair.turn(grant,|cx|left.as_mut().unwrap().with_native_pair(right.as_mut().unwrap(),cx,|left,right,_|{assert!(!std::ptr::eq(left,right));Ok(())})).unwrap());assert!(pair.turn(grant,|cx|right.as_mut().unwrap().with_native_pair(left.as_mut().unwrap(),cx,|left,right,_|{assert!(!std::ptr::eq(left,right));Ok(())})).unwrap());assert!(pair.turn(grant,|cx|left.as_mut().unwrap().with_native_pair(alias.as_mut().unwrap(),cx,|_,_,_|Ok(()))).is_err());assert!(foreign.turn(grant,|cx|left.as_mut().unwrap().with_native_pair(right.as_mut().unwrap(),cx,|_,_,_|Ok(()))).is_err());let left_id=left.as_ref().unwrap().recipient_identity();let right_id=right.as_ref().unwrap().recipient_identity();let accepted=pair.turn(grant,|cx|left.as_mut().unwrap().with_native_pair_borrow(right.as_mut().unwrap(),cx,|mut a,mut b,_|{assert_eq!(a.recipient_identity(),left_id);assert_eq!(b.recipient_identity(),right_id);assert!(!std::ptr::eq(a.value_mut(),b.value_mut()));Ok(())})).unwrap();assert_eq!(accepted,cases["guard"]["pairSameSource"].as_bool().unwrap());let refused=pair.turn(grant,|cx|left.as_mut().unwrap().with_native_pair_borrow(alias.as_mut().unwrap(),cx,|_,_,_|Ok(()))).is_err();assert_eq!(refused,cases["guard"]["pairAliasRefused"].as_bool().unwrap());let refused=foreign.turn(grant,|cx|left.as_mut().unwrap().with_native_pair_borrow(right.as_mut().unwrap(),cx,|_,_,_|Ok(()))).is_err();assert_eq!(refused,cases["guard"]["pairForeignRefused"].as_bool().unwrap());drop(alias);drop(left);drop(right);while !pair.turn(grant,|cx|cx.close_original_native_step()).unwrap(){}pair.retire(grant);foreign.retire(grant);
 for (index,row) in cases["cases"].as_array().unwrap().iter().enumerate(){
  let mut caller=OriginalJobFixtureCaller::admit(OperationId(620+index as u64),Generation(1),grant,clock,100000,100000);prebirth(&mut caller,grant);let mut foreign=OriginalJobFixtureCaller::admit(OperationId(630+index as u64),Generation(1),grant,clock,100000,100000);let mut owner:Option<OriginalNativeLease<Native>>=None;let mut child=None;let mut outputs=Vec::new();
  for event in row["events"].as_array().unwrap(){let output=match event.as_str().unwrap(){
   "birth"=>{let mut input=Some(Native{empty:false});assert!(caller.turn(grant,|cx|cx.admit_original_native(&mut input,&mut owner)).unwrap());"admitted"},
   "lend"=>{assert!(caller.turn(grant,|cx|owner.as_ref().unwrap().lend(cx,&mut child)).unwrap());"borrowed"},
   "foreignBorrow"=>{assert!(foreign.turn(grant,|cx|owner.as_mut().unwrap().with_native(cx,|_,_|Ok(()))).is_err());"refused"},
   "cancel"=>{caller.cancel().cancel_now();"retained"},
   "dropCaller"=>{drop(owner.take());drop(child.take());"captured"},
   "return"=>{let loan=if child.is_some(){&mut child}else{&mut owner};while loan.is_some(){caller.turn(grant,|cx|OriginalNativeLease::return_slot_step(loan,cx)).unwrap();}"returned"},
   "close"=>{while owner.is_some(){caller.turn(grant,|cx|OriginalNativeLease::return_slot_step(&mut owner,cx)).unwrap();}loop{let before=caller.fuel_remaining();let complete=caller.turn(grant,|cx|cx.close_original_native_step()).unwrap();if complete{break "closed"}if before==caller.fuel_remaining(){break "blocked"}}},
   _=>unreachable!()};outputs.push(output);
  }
  assert_eq!(serde_json::json!(outputs),row["outputs"]);drop(owner);drop(child);caller.retire(grant);foreign.retire(grant);
 }
}

#[test]
fn exact_recipient_closure_keeps_sibling_live_without_global_forfeit_evidence(){
 struct Leaf(bool);impl OriginalNativeRetirement for Leaf{fn close_on_source(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{cx.consume_fuel(1);self.0=true;Ok(true)}fn terminal_is_empty(&self)->bool{self.0}}impl Drop for Leaf{fn drop(&mut self){assert!(std::thread::panicking()||self.0)}}
 let law:serde_json::Value=serde_json::from_str(include_str!("cases.json")).unwrap();let law=&law["individualClosure"];let grant=stock();let mut caller=OriginalJobFixtureCaller::admit(OperationId(701),Generation(1),grant,clock,100000,100000);prebirth(&mut caller,grant);let mut foreign=OriginalJobFixtureCaller::admit(OperationId(702),Generation(1),grant,clock,100000,100000);let(mut left,mut right)=(None,None);let mut input=Some(Leaf(false));assert!(caller.turn(grant,|cx|cx.admit_original_native(&mut input,&mut left)).unwrap());let mut input=Some(Leaf(false));assert!(caller.turn(grant,|cx|cx.admit_original_native(&mut input,&mut right)).unwrap());let id=left.as_ref().unwrap().recipient_identity();assert_eq!(caller.turn(grant,|cx|cx.original_native_recipient_closed(id)).unwrap().is_some(),law["before"].as_bool().unwrap());assert_eq!(foreign.turn(grant,|cx|cx.original_native_recipient_closed(id)).is_err(),law["foreignRefused"].as_bool().unwrap());drop(left);
 let mut proof=false;for _ in 0..256{caller.turn(grant,|cx|cx.close_original_native_step()).unwrap();proof=caller.turn(grant,|cx|{let witness=cx.original_native_recipient_closed(id)?;Ok(witness.is_some_and(|witness|witness.proves(id,cx)))}).unwrap();if proof{break}}assert_eq!(proof,law["after"].as_bool().unwrap());assert_eq!(caller.turn(grant,|cx|right.as_mut().unwrap().with_native(cx,|leaf,_|{assert!(!leaf.0);Ok(())})).unwrap(),law["siblingLive"].as_bool().unwrap());assert_eq!(caller.turn(grant,|cx|cx.original_native_retired_witness(id)).unwrap().is_some(),law["globalWitness"].as_bool().unwrap());drop(right);for _ in 0..256{if caller.turn(grant,|cx|cx.close_original_native_step()).unwrap(){break}}caller.retire(grant);foreign.retire(grant);
}

#[test]
fn native_cleanup_selects_vm_credit_only_for_the_next_actual_owner(){
 struct Vm(bool);impl OriginalNativeRetirement for Vm{fn close_on_source(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{cx.consume_fuel(1);self.0=true;Ok(true)}fn terminal_is_empty(&self)->bool{self.0}fn close_requires_execution(&self)->bool{!self.0}}impl Drop for Vm{fn drop(&mut self){assert!(std::thread::panicking()||self.0)}}
 let law:serde_json::Value=serde_json::from_str(include_str!("cases.json")).unwrap();let law=&law["nativeExecution"];let grant=stock();let mut caller=OriginalJobFixtureCaller::admit(OperationId(703),Generation(1),grant,clock,100000,100000);prebirth(&mut caller,grant);let mut owner=None;let mut input=Some(Vm(false));assert!(caller.turn(grant,|cx|cx.admit_original_native(&mut input,&mut owner)).unwrap());assert_eq!(caller.turn(grant,|cx|Ok(cx.original_source_parent()?.native_close_requires_execution())).unwrap(),Some(law["ordinary"].as_bool().unwrap()));drop(owner);assert_eq!(caller.turn(grant,|cx|Ok(cx.original_source_parent()?.native_close_requires_execution())).unwrap(),Some(law["pendingReturn"].as_bool().unwrap()));let mut selected=false;for _ in 0..64{let next=caller.turn(grant,|cx|Ok(cx.original_source_parent()?.native_close_requires_execution())).unwrap();if next==Some(true){selected=true;break}caller.turn(grant,|cx|cx.close_original_native_step()).unwrap();}assert_eq!(selected,law["guest"].as_bool().unwrap());for _ in 0..64{if caller.turn(grant,|cx|cx.close_original_native_step()).unwrap(){break}}caller.retire(grant);
}

#[test]
fn source_escrow_birth_refuses_insufficient_total_and_yields_for_a_small_turn(){
 let cases:serde_json::Value=serde_json::from_str(include_str!("cases.json")).unwrap();let(copy,capacity,_)=semio_framework_job_payload::OriginalReturnEscrowTable::birth_demand();let all=stock();let probe=OriginalJobFixtureCaller::admit(OperationId(690),Generation(1),all,clock,100000,100000);let birth=probe.cumulative_receipt().copied_bytes;probe.retire(all);let funded=RetainedCloneGrant{maximum_copy_bytes:birth+copy-1,..all};let mut denied=OriginalJobFixtureCaller::admit(OperationId(691),Generation(1),funded,clock,100000,100000);
 let refused=denied.turn(RetainedCloneGrant{maximum_copy_bytes:copy,..all},|cx|cx.admit_original_return_table()).is_err();assert_eq!(refused,cases["escrowBirth"]["underfundedRefused"].as_bool().unwrap());assert_eq!(denied.receipt(),Default::default());denied.retire(funded);
 let mut caller=OriginalJobFixtureCaller::admit(OperationId(692),Generation(1),all,clock,100000,100000);let one=RetainedCloneGrant{maximum_items:1,..all};assert!(!caller.turn(one,|cx|cx.admit_original_return_table()).unwrap());let tiny=RetainedCloneGrant{maximum_copy_bytes:0,..one};let pending=!caller.turn(tiny,|cx|cx.admit_original_return_table()).unwrap();assert_eq!(pending,cases["escrowBirth"]["zeroCopyQuantumPending"].as_bool().unwrap());assert_eq!(caller.receipt(),Default::default());
 let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(one,|cx|cx.admit_original_return_table()));assert_eq!(result.unwrap(),cases["escrowBirth"]["oneItemAdmitted"].as_bool().unwrap());assert_eq!(caller.receipt().copied_items,1);assert_eq!(caller.receipt().copied_bytes,copy);assert_eq!(caller.receipt().retained_capacity_bytes,capacity);assert_eq!(heap.requested_bytes,capacity);caller.record_born_capacity(capacity);caller.retire(all);
}
